            self.faults = try c.decodeIfPresent(UInt64.self, forKey: .faults) ?? 0
        }

        public func encode(to encoder: any Encoder) throws {
            var c = encoder.container(keyedBy: CodingKeys.self)
            try c.encode(self.state, forKey: .state)
            if self.reason != "" { try c.encode(self.reason, forKey: .reason) }
            try c.encode(self.sizeBytes, forKey: .sizeBytes)
            if self.reads != 0 { try c.encode(self.reads, forKey: .reads) }
            if self.mappings != 0 { try c.encode(self.mappings, forKey: .mappings) }
            if self.live != 0 { try c.encode(self.live, forKey: .live) }
            if self.faults != 0 { try c.encode(self.faults, forKey: .faults) }
        }
    }
}

